import Foundation
import HomeswiftAI

/// Original AI-generated photographic artwork. Titles are shared catalogue names, kept in every language.
/// Palettes are approximate sRGB conversions, not a reproduction of Hue brightness or animations.
public struct SceneArtwork: Sendable {
    public let id: String
    public let name: String
    public let colors: [MoodColor]
    public var json: JSONValue { ["id": .string(id), "name": .string(name)] }
    public var mood: Mood {
        Mood(id: "gallery-" + id, name: name, description: "Photographic colour palette.", category: "gallery",
             steps: [MoodStep(colors, assign: .spread, seconds: 1)])
    }
    public static func find(_ id: String) -> SceneArtwork? { all.first { $0.id == id } ?? moodPhotographs.first { $0.id == id } }
    public static func forMood(_ id: String?) -> SceneArtwork? {
        guard let id else { return nil }
        if id.hasPrefix("gallery-") { return find(String(id.dropFirst(8))) }
        return moodArtwork[id].flatMap(find)
    }
    /// Dedicated photographs for effects whose subjects are absent from the scene gallery.
    private static let moodPhotographs: [SceneArtwork] = [
        SceneArtwork(id: "mood-candle-flicker", name: "Candle flicker", colors: []),
